content.content:
/**
 * Build a roof. footprint: the WALL footprint (outer faces) as a rect or union of rects. opts:
 *   y            the eave course (wall top + 1)                                    (required)
 *   material     a palette ("slate", "spruce-shingle", ...), a block (mixed by autoMix) or { mix:[[block,w]..], eave, ridge, verge .. }
 *   texture      false = the one named block only (a guard-rail warning)   trim   cornice / verge / dentil material
 *   pitch        half | 45 | steep | very-steep | number                  overhang 0..2, or { north, south, east, west } (default 1)
 *   eave         plain | flared | cornice                                  soffit  slab material under the overhang
 *   ridge        slab | wall | crest | rods | none | a block name          ridgeAxis "x" | "z" (gable wings; default the long side)
 *   gable        gable-end wall block (default: the wall block under the eave)   verge  barge-course material
 *   hips         material for the hip stairs                               pattern { material, every, offset }
 *   lower, upperPitch  (mansard, gambrel)                                  low     the low side of a shed
 *   dormers      { face (a side, "all" or a list), count | every, style: gable|shed|eyebrow, width, height, window, wall,
 *                cheek (default: the verge timber, so the dormer is framed dark round its face) }
 *   pediment     { face, width, pitch, tympanum, oculus } (face string also works)
 *   chimneys     [[x,z] | { at, size, material, rise }]   (rise from the local roof surface, default 2)
 *   tower        { at:[x,z], size, height, top: lantern|spire|cap, material, from }
 *   edges        false | { fascia, soffit, barge } (default all on when the overhang is 1+): an open-trapdoor fascia on the
 *                outer face of the eave, soffit slabs under the overhang, a barge course on gable ends. fascia: a block name.
 *   maxHeight    roof height cap in courses: the pitch steps down 3 > 2 > 1 > 0.5 until it fits
 *   cantilever   (flat-parapet) extend the deck by the overhang, with a fascia and soffit
 *   materialAt   ({ x, z, course, courses, role, full }) -> block name; role: field|eave|ridge|verge|hip|fascia|soffit
 *   heightMod    (H, info) -> { puts } mutate the height map (Map "x,z" -> blocks above the eave); puts: [[x, dy, z, [block, state]]]
 *   dryRun       compute everything, write nothing: returns { dryRun: true, facts, notes }
 *   keep         [{from:[x,y,z], to:[x,y,z]}] never written; protect: Set "x,y,z" (default: the grid's functional cells)
 *   grow         grow the grid to fit (default true)
 * Returns { cells, refused, shift, eave: y, top, footprint, notes, facts }.
 */
export function roof(g, footprint, style = "hip", o = {}) {
  if (ROOF_PRESETS[style] || o.preset) {                                   // a preset: good options by construction, flags override
    const name = ROOF_PRESETS[style] ? style : o.preset, { preset, ...rest } = o;
    if (!ROOF_PRESETS[name]) throw new Error(`roof: unknown preset ${name} (${Object.keys(ROOF_PRESETS).join(", ")})`);
    const p = presetOptions(name, g, rectsOf(footprint), rest);
    return roof(g, footprint, rest.style && ROOF_STYLES.includes(rest.style) ? rest.style : p.style, { ...p, ...Object.fromEntries(Object.entries(rest).filter(([k]) => k !== "style")), _notes: p._notes, _preset: name });
  }
  if (!ROOF_STYLES.includes(style)) throw new Error(`roof: unknown style ${style} (${ROOF_STYLES.join(", ")})`);
  if (o.y == null) throw new Error("roof: opts.y (the eave course: wall top + 1) is required");
  const rects = rectsOf(footprint), y0 = o.y, W = writer(), notes = [...(o._notes || [])];
  let P = pitchOf(o.pitch ?? 45);
  // material: a palette / mix / block becomes a texture (materialAt by role) unless texture:false or the caller brings a hook
  const texSeed = o.seed ?? 0;
  const baseOf = (n) => { const mix = ROOF_PALETTES[n]?.mix ?? (Array.isArray(n) ? n : n?.mix); return mix ? mix.find((m) => m[2] !== "full")[0] : n; };
  const resolve = (n) => {
    if (o.texture === false || o.materialAt || (typeof n === "string" && NO_STAIRS.test(materialOf(n).prefix))) return { tex: null, base: o.texture === false && o.material == null ? "deepslate_tile" : baseOf(n) };   // texture:false with no material is the legacy single block
    try { const tex = textureOf(n, { seed: texSeed }); return { tex, base: tex.members.find((m) => !m.fullOnly).block }; } catch { return { tex: null, base: baseOf(n) }; }
  };
  const given = o.material ?? DEFAULT_MATERIAL;
  let { tex, base } = resolve(given);
  let mat = materialOf(base);
  const trim = materialOf(o.trim ?? base);
  for (const [label, m] of [["material", mat], ["trim", trim]]) if (NO_STAIRS.test(m.prefix)) notes.push(`${label} ${m.prefix} has no stairs or slabs: the roof would place invalid blocks (use a brick, tile, plank, cut-stone or cut-copper material)`);
  const fc = o.protect ?? (() => { const f = functionalCells(g); return new Set([...f.protect.keys(), ...f.keepClear]); })();
  const M0 = maskOf(rects, 0), R0 = largest(rects), wallH = wallHeightOf(g, R0, y0);
  const wallAt = (x, z) => { const b = g.inBounds(x, y0 - 1, z) ? strip(g.blockAt(x, y0 - 1, z)) : null; return b && !AIR.test(b) && !/stairs|slab|glass|pane|door|fence|wall$/.test(b) ? b : null; };
  const tally = new Map();                                                  // the walls' own block, for gables inside the plan
  for (const k of M0) { const [x, z] = XZ(k); if (CARD.some((d) => !M0.has(K(...step(x, z, d))))) { const b = wallAt(x, z); if (b) tally.set(b, (tally.get(b) || 0) + 1); } }
  const mainWall = [...tally].sort((a, b) => b[1] - a[1])[0]?.[0];
  // contrast: a roof must read as a roof, not as more wall (tone measured from the textures, families.mjs)
  const contrast = { checked: o.contrast === false, off: o.contrast === false, distance: null };
  if (o.contrast !== false && mainWall && style !== "flat-parapet") {
