    material: { mix: [["deepslate_tile", 50], ["cobbled_deepslate", 30], ["polished_blackstone_brick", 20]], eave: "polished_blackstone_brick", ridge: "stone_brick", verge: "dark_oak" },   // dark-glazed with a stone-grey ridge (not quartz white) overhang: 1, 
