  church: () => ({ style: "tiered", tiers: 3, material: { mix: [["dark_oak", 40], ["spruce", 30], ["mangrove", 15], ["cobbled_deepslate", 15]], eave: "dark_oak", ridge: "dark_oak", gradient: "none" }, pitches: [1, 1.5, 2], overhang: 1, ridgeEnds: "dragon", ste
  workshop: () => ({ style: "sawtooth", material: "copper", pitch: 1, glaze: "north", overhang: 0, steep: true }),
  desert: (P) => ({
    style: "flat-parapet", parapet: 1, material: { mix: [["smooth_sandstone", 60], ["sandstone", 25], ["mud_brick", 15]], eave: "smooth_quartz", ridge: "smooth_quartz", gradient: "none" }, trim: "smooth_quartz", overhang: 0, steep: true,
