    ridgeAxis: "x", front: "north", pitch: 45, y: 6,
    edges: EDGES, trim: "birch_planks", overhang: { north: 1, south: 1, east: 0, west: 0 }, material: { mix: [["dark_oak_planks", 3], ["spruce_planks", 1]] },
