  for (let x = 61; x <= 70; x++) for (let y = 7; y <= 24; y++) for (let z = 7; z <= 17; z++) {
    const c = g.get(x, y, z);
    if (c?.block === "minecraft:iron_bars") g.set(x, y, z, "spruce_fence", c.state);
  }
