  for (let x = 36; x <= 48; x++) for (let y = 6; y <= 14; y++) for (let z = 6; z <= 12; z++) { const b = g.blockAt(x + (r.shift?.[0] ?? 0), y, z); if (/stone_brick|birch_slab/.test(b)) hits.push(`${x},${y},${z} ${b.replace("minecraft:", "")}`); }
  console.log(name, "shift", r.shift, "hits", hits.join("; "));
}
